PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://moosedev.dev/kg/ontology/software-architecture/>
SELECT ?iri ?title WHERE {
  ?iri rdf:type moose:Constraint ;
       rdfs:label ?title .
  FILTER NOT EXISTS { ?iri moose:lifecycleStatus "deprecated" }
  FILTER NOT EXISTS { ?iri moose:lifecycleStatus "superseded" }
}
ORDER BY ?title

